// The Steam fm.exe's code the harness depends on, as masked byte patterns (generated by
// tools/probe/gen_probe_patterns.py into probe_patterns.c). `fm24ctl probe` finds them in another
// build of fm.exe.
#pragma once

#include <stddef.h>
#include <stdint.h>


// One function of the Steam build: `size` bytes at probePatternBytes[byteOffset], with a mask of
// one bit per byte at probePatternMask[maskOffset] (set: the byte must match; clear: it holds an
// address that moves between builds).
typedef struct ProbeFunction {
	const char *name;
	const char *uses; // why the harness needs it: game.h names, "sites", or a data reference
	uint32_t rva;
	uint32_t size;
	uint32_t byteOffset;
	uint32_t maskOffset;
} ProbeFunction;

// One game.h data address, found through a RIP-relative instruction that references it:
// probeFunctions[function] + instruction, whose 32-bit displacement is at + operand.
typedef struct ProbeData {
	const char *name;
	uint32_t rva;
	uint32_t function;
	uint32_t instruction;
	uint32_t operand;
	uint32_t instructionSize;
} ProbeData;

extern const uint8_t probePatternBytes[];
extern const uint8_t probePatternMask[];
extern const ProbeFunction probeFunctions[];
extern const size_t probeFunctionCount;
extern const ProbeData probeData[];
extern const size_t probeDataCount;
